public class NDXProdTableProdIdentReport extends common
{
}

Method.Source:
/// <summary>
/// PaffH 18.12.24
/// </summary>
/// <param name = "_prodTableRecId">ProdTable recId</param>
/// <param name = "_forUpdate">for update</param>
/// <returns>NDXProdTableProdIdentReport</returns>
public static NDXProdTableProdIdentReport find(RecId _prodTableRecId, boolean _forUpdate = false)
{
    NDXProdTableProdIdentReport nDXProdTableProdIdentReport;
    nDXProdTableProdIdentReport.selectForUpdate(_forUpdate);
    select firstonly nDXProdTableProdIdentReport
        where nDXProdTableProdIdentReport.ProdTable == _prodTableRecId;
    return nDXProdTableProdIdentReport;
}

/// <summary>
/// PaffH 18.12.24
/// </summary>
/// <param name = "_prodTable">ProdTable</param>
/// <param name = "_insert">boolean</param>
/// <returns>NDXProdTableProdIdentReport</returns>
public static NDXProdTableProdIdentReport findOrCreate(ProdTable _prodTable, boolean _insert = true)
{
    NDXProdTableProdIdentReport nDXProdTableProdIdentReport;
    nDXProdTableProdIdentReport = NDXProdTableProdIdentReport::find(_prodTable.RecId, true);
    if (!nDXProdTableProdIdentReport)
    {
        nDXProdTableProdIdentReport.ProdTable = _prodTable.RecId;
        nDXProdTableProdIdentReport.StartupRelease = 
            _prodTable.status().isAfterOrEqualTo(ProdStatus::StartedUp) ? 
            NDXStartupRelease::Startup :
            NDXStartupRelease::Release;
        nDXProdTableProdIdentReport.ProdStatus = _prodTable.ProdStatus;
        nDXProdTableProdIdentReport.ProdPoolId = _prodTable.ProdPoolId;
        if (_insert)
        {
            nDXProdTableProdIdentReport.insert();
        }
    }
    return nDXProdTableProdIdentReport;
}

/// <summary>
/// PaffH 18.12.24
/// </summary>
/// <param name = "_prodTable">ProdTable</param>
/// <param name = "_insert">boolean</param>
/// <returns>NDXProdTableProdIdentReport</returns>
public static NDXProdTableProdIdentReport findOrCreateUpdate(ProdTable _prodTable, boolean _insert = true)
{
    NDXProdTableProdIdentReport nDXProdTableProdIdentReport;
    nDXProdTableProdIdentReport = NDXProdTableProdIdentReport::find(_prodTable.RecId, true);
    if (!nDXProdTableProdIdentReport)
    {
        nDXProdTableProdIdentReport = NDXProdTableProdIdentReport::findOrCreate(_prodTable, _insert);
    }
    else
    {
        nDXProdTableProdIdentReport.StartupRelease =
            _prodTable.status().isAfterOrEqualTo(ProdStatus::StartedUp) ?
            NDXStartupRelease::Startup :
            NDXStartupRelease::Release;
        nDXProdTableProdIdentReport.ProdStatus = _prodTable.ProdStatus;
        nDXProdTableProdIdentReport.ProdPoolId = _prodTable.ProdPoolId;
        ttsbegin;
        if (nDXProdTableProdIdentReport.validateWrite())
        {
            nDXProdTableProdIdentReport.update();
        }
        ttscommit;
    }
    return nDXProdTableProdIdentReport;
}

/// <summary>
/// PaffH 18.12.24
/// </summary>
/// <returns>already printed</returns>
public boolean printed()
{
    return (this.RecId != 0);
}
